-- SEFAES canonical actor onboarding and authentication
-- One provisioning contract. Human login IDs are generated by the database.
begin;

create extension if not exists pgcrypto;
create sequence if not exists public.actor_login_id_seq;
create sequence if not exists public.student_number_seq;
alter table public.profiles add column if not exists email text;
alter table public.profiles
  add column if not exists authority_user_id uuid references auth.users(id) on delete restrict;
alter table public.identity_actors
  add column if not exists authority_user_id uuid references auth.users(id) on delete restrict;
create index if not exists profiles_authority_user_id_idx
  on public.profiles(authority_user_id);
create index if not exists identity_actors_authority_user_id_idx
  on public.identity_actors(authority_user_id);

alter table public.profiles drop constraint if exists profiles_role_check;
alter table public.profiles add constraint profiles_role_check
  check (role = any (array[
    'principal_admin','vice_principal','bursar','teacher','student','parent',
    'examiner','individual','admin','dean','hod','adviser','lecturer'
  ]));

alter table public.identity_actors drop constraint if exists identity_actors_actor_type_check;
alter table public.identity_actors add constraint identity_actors_actor_type_check
  check (actor_type = any (array[
    'superadmin','principal_admin','vice_principal','bursar','teacher','student','parent',
    'dean','hod','adviser','lecturer'
  ]));

-- Retire every historical onboarding overload. Frontend callers must use actor-onboarding.
do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as signature
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'create_teacher','create_vp','create_bursar','enroll_student',
        'create_parent','bulk_enroll_students','create_student_profile',
        'create_staff_profile','authenticate_actor','sub_account_pin_login',
        'set_pin','reset_user_pin'
      )
  loop
    execute format('drop function %s', f.signature);
  end loop;
end $$;

create or replace function public.complete_actor_onboarding(
  p_auth_user_id uuid,
  p_authority_user_id uuid,
  p_expected_authority_role text,
  p_actor_type text,
  p_school_id uuid,
  p_institution_id uuid,
  p_full_name text,
  p_pin text,
  p_email text default null,
  p_phone text default null,
  p_student_id uuid default null,
  p_class_id uuid default null,
  p_class_subject_ids uuid[] default null,
  p_gender text default null,
  p_date_of_birth date default null,
  p_relationship text default 'Parent',
  p_is_primary boolean default true,
  p_faculty_id uuid default null,
  p_department_id uuid default null,
  p_title text default null,
  p_rank text default null,
  p_specialization text default null,
  p_is_graduate_student_supervisor boolean default false,
  p_max_students integer default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_prefix text;
  v_login_id text;
  v_profile_id uuid;
  v_actor_record_id uuid;
  v_student_number text;
  v_first_name text;
  v_last_name text;
  v_effective_school_id uuid := p_school_id;
  v_authority public.profiles%rowtype;
  v_expected_actor_roles text[];
begin
  if p_auth_user_id is null or p_authority_user_id is null then
    raise exception 'AUTH_USER_AND_AUTHORITY_REQUIRED';
  end if;
  if p_auth_user_id = p_authority_user_id then raise exception 'SELF_PROVISIONING_DENIED'; end if;
  select * into v_authority
  from public.profiles
  where user_id = p_authority_user_id;
  if not found then raise exception 'AUTHORITY_PROFILE_NOT_FOUND'; end if;
  if v_authority.role <> p_expected_authority_role then raise exception 'INVALID_AUTHORITY_ROLE'; end if;
  if v_authority.institution_id is distinct from p_institution_id then
    raise exception 'CROSS_INSTITUTION_AUTHORITY_DENIED';
  end if;
  if p_expected_authority_role = 'principal_admin' then
    v_expected_actor_roles := array['vice_principal','bursar','teacher','student','parent'];
    if v_authority.school_id is distinct from p_school_id then
      raise exception 'CROSS_SCHOOL_AUTHORITY_DENIED';
    end if;
    if not exists (
      select 1 from public.identity_actors ia
      where ia.auth_user_id = p_authority_user_id
        and ia.actor_type = 'principal_admin'
        and ia.status = 'active'
    ) then raise exception 'ACTIVE_PRINCIPAL_ACTOR_REQUIRED'; end if;
  elsif p_expected_authority_role = 'dean' then
    v_expected_actor_roles := array['vice_principal','bursar','teacher','student','parent','hod','adviser','lecturer'];
  else
    raise exception 'UNSUPPORTED_AUTHORITY_ROLE';
  end if;
  if p_actor_type is null or not (p_actor_type = any(v_expected_actor_roles)) then
    raise exception 'ACTOR_ROLE_NOT_ALLOWED_FOR_AUTHORITY';
  end if;
  if p_actor_type not in ('vice_principal','bursar','teacher','student','parent','hod','adviser','lecturer') then
    raise exception 'UNSUPPORTED_ACTOR_TYPE';
  end if;
  if nullif(trim(p_full_name), '') is null then raise exception 'FULL_NAME_REQUIRED'; end if;
  if p_pin is null or p_pin !~ '^[0-9]+
    raise exception 'INVALID_PIN_LENGTH';
  end if;
  if not exists (select 1 from public.institutions i where i.id = p_institution_id) then
    raise exception 'INSTITUTION_NOT_FOUND';
  end if;
  if p_school_id is not null and not exists (
    select 1 from public.schools s where s.id = p_school_id and s.institution_id = p_institution_id
  ) then raise exception 'SCHOOL_INSTITUTION_MISMATCH'; end if;

  if p_actor_type in ('vice_principal','bursar','teacher','student','lecturer') and p_school_id is null then raise exception 'SCHOOL_REQUIRED'; end if;

  v_prefix := case p_actor_type
    when 'vice_principal' then 'VP'
    when 'bursar' then 'BUR'
    when 'teacher' then 'TCH'
    when 'student' then 'STU'
    when 'parent' then 'PAR'
    when 'dean' then 'DEAN'
    when 'hod' then 'HOD'
    when 'adviser' then 'ADV'
    when 'lecturer' then 'LEC'
  end;
  v_login_id := v_prefix || '-' || lpad(nextval('public.actor_login_id_seq')::text, 8, '0');

  if p_actor_type = 'teacher' and coalesce(cardinality(p_class_subject_ids), 0) > 0 then
    if exists (
      select 1
      from unnest(p_class_subject_ids) requested(class_subject_id)
      where not exists (
        select 1 from public.class_subjects cs
        where cs.id = requested.class_subject_id
          and cs.school_id = p_school_id
          and (cs.institution_id is null or cs.institution_id = p_institution_id)
      )
    ) then raise exception 'CLASS_SUBJECT_NOT_IN_SCHOOL'; end if;
  end if;

  if p_actor_type = 'student' then
    if length(trim(p_full_name)) <= length(split_part(trim(p_full_name), ' ', 1)) then raise exception 'STUDENT_LAST_NAME_REQUIRED'; end if;
    if p_class_id is null or not exists (
      select 1 from public.classes c where c.id = p_class_id and c.school_id = p_school_id
    ) then raise exception 'CLASS_NOT_IN_SCHOOL'; end if;
  end if;

  if p_actor_type = 'parent' then
    select s.school_id into v_effective_school_id
    from public.students s
    where s.id = p_student_id
      and s.institution_id = p_institution_id
      and (p_school_id is null or s.school_id = p_school_id);
    if p_student_id is null or not found then raise exception 'LINKED_STUDENT_NOT_FOUND'; end if;
  end if;

  insert into public.profiles (
    user_id, institution_id, school_id, full_name, role, email, phone,
    authentication_method, pin, pin_hash, pin_type, pin_requires_change,
    pin_changed_at, failed_attempts, locked_until
  ) values (
    p_auth_user_id, p_institution_id, v_effective_school_id, trim(p_full_name), p_actor_type,
    nullif(trim(p_email), ''), nullif(trim(p_phone), ''),
    'pin', null, crypt(p_pin, gen_salt('bf')), 
    case when p_actor_type in ('student','parent') then '4-digit' else '6-digit' end,
    true, null, 0, null
  ) returning id into v_profile_id;

  if p_actor_type = 'teacher' then
    insert into public.teachers(user_id, institution_id, school_id, name, email, phone)
    values (p_auth_user_id, p_institution_id, p_school_id, trim(p_full_name),
      nullif(trim(p_email), ''), nullif(trim(p_phone), ''))
    returning id into v_actor_record_id;
    if coalesce(cardinality(p_class_subject_ids), 0) > 0 then
      insert into public.teacher_subject_assignments(school_id, teacher_id, class_subject_id)
      select p_school_id, v_actor_record_id, requested.class_subject_id
      from (
        select distinct unnest(p_class_subject_ids) as class_subject_id
      ) requested;
    end if;
  elsif p_actor_type = 'vice_principal' then
    insert into public.vice_principals(profile_id, school_id, full_name, email, phone)
    values (v_profile_id, p_school_id, trim(p_full_name),
      nullif(trim(p_email), ''), nullif(trim(p_phone), ''))
    returning id into v_actor_record_id;
  elsif p_actor_type = 'bursar' then
    insert into public.bursars(profile_id, school_id, full_name, email, phone)
    values (v_profile_id, p_school_id, trim(p_full_name),
      nullif(trim(p_email), ''), nullif(trim(p_phone), ''))
    returning id into v_actor_record_id;
  elsif p_actor_type = 'student' then
    v_student_number := 'GRD/' || to_char(now(), 'YYYY') || '/' || lpad(nextval('public.student_number_seq')::text, 6, '0');
    insert into public.students(
      user_id, institution_id, school_id, class_id, student_number,
      first_name, last_name, gender, date_of_birth, email, phone
    ) values (
      p_auth_user_id, p_institution_id, p_school_id, p_class_id, v_student_number,
      split_part(trim(p_full_name), ' ', 1),
      nullif(btrim(substr(trim(p_full_name), length(split_part(trim(p_full_name), ' ', 1)) + 2)), ''),
      p_gender, p_date_of_birth, nullif(trim(p_email), ''), nullif(trim(p_phone), '')
    ) returning id into v_actor_record_id;
  elsif p_actor_type in ('dean','hod','adviser') then
    if p_actor_type = 'dean' then
      if p_faculty_id is null or not exists (
        select 1 from public.nuc_faculties nf where nf.id = p_faculty_id and nf.institution_id = p_institution_id
      ) then raise exception 'NUC_FACULTY_NOT_IN_INSTITUTION'; end if;
    elsif p_actor_type = 'hod' then
      if p_department_id is null or not exists (
        select 1 from public.nuc_departments nd where nd.id = p_department_id and nd.institution_id = p_institution_id
      ) then raise exception 'NUC_DEPARTMENT_NOT_IN_INSTITUTION'; end if;
    elsif p_department_id is not null and not exists (
      select 1 from public.departments d where d.id = p_department_id and d.institution_id = p_institution_id
    ) then raise exception 'DEPARTMENT_NOT_IN_INSTITUTION'; end if;

    insert into public.faculty(institution_id, department_id, full_name, email, role)
    values (p_institution_id, case when p_actor_type = 'adviser' then p_department_id else null end,
      trim(p_full_name), coalesce(nullif(trim(p_email), ''), v_login_id || '@accounts.sefaes.invalid'), p_actor_type)
    returning id into v_actor_record_id;

    if p_actor_type = 'dean' then
      update public.nuc_faculties
      set dean_id = v_actor_record_id, dean_name = trim(p_full_name),
          dean_email = nullif(trim(p_email), ''), updated_at = now()
      where id = p_faculty_id and institution_id = p_institution_id;
    elsif p_actor_type = 'hod' then
      update public.nuc_departments
      set hod_id = v_actor_record_id, hod_name = trim(p_full_name),
          hod_email = nullif(trim(p_email), ''), updated_at = now()
      where id = p_department_id and institution_id = p_institution_id;
    end if;
  elsif p_actor_type = 'lecturer' then
    if length(trim(p_full_name)) <= length(split_part(trim(p_full_name), ' ', 1)) then
      raise exception 'LECTURER_LAST_NAME_REQUIRED';
    end if;
    if p_department_id is not null and not exists (
      select 1 from public.nuc_departments d where d.id = p_department_id and d.institution_id = p_institution_id
    ) then raise exception 'NUC_DEPARTMENT_NOT_IN_INSTITUTION'; end if;
    if p_faculty_id is not null and not exists (
      select 1 from public.nuc_faculties f where f.id = p_faculty_id and f.institution_id = p_institution_id
    ) then raise exception 'NUC_FACULTY_NOT_IN_INSTITUTION'; end if;
    if nullif(trim(p_email), '') is null then raise exception 'LECTURER_EMAIL_REQUIRED'; end if;
    insert into public.lecturers(
      school_id, user_id, title, first_name, last_name, email, phone,
      department_id, faculty_id, rank, specialization,
      is_graduate_student_supervisor, max_students
    ) values (
      p_school_id, p_auth_user_id, nullif(trim(p_title), ''),
      split_part(trim(p_full_name), ' ', 1),
      nullif(btrim(substr(trim(p_full_name), length(split_part(trim(p_full_name), ' ', 1)) + 2)), ''),
      trim(p_email), nullif(trim(p_phone), ''), p_department_id, p_faculty_id,
      nullif(trim(p_rank), ''), nullif(trim(p_specialization), ''),
      coalesce(p_is_graduate_student_supervisor, false), p_max_students
    ) returning id into v_actor_record_id;
  elsif p_actor_type = 'parent' then
    insert into public.parents(institution_id, profile_id, child_student_id)
    values (p_institution_id, v_profile_id, p_student_id)
    returning id into v_actor_record_id;
    insert into public.student_parents(student_id, parent_id, relationship, is_primary)
    values (p_student_id, v_actor_record_id, coalesce(nullif(trim(p_relationship), ''), 'Parent'), coalesce(p_is_primary, true));
    insert into public.student_parent_relationships(
      institution_id, school_id, student_id, parent_id, relationship_type, is_primary
    ) values (
      p_institution_id, v_effective_school_id, p_student_id, v_actor_record_id,
      case lower(coalesce(nullif(trim(p_relationship), ''), 'other'))
        when 'father' then 'father'
        when 'mother' then 'mother'
        when 'guardian' then 'guardian'
        else 'other'
      end,
      coalesce(p_is_primary, true)
    );
  end if;

  insert into public.identity_actors(
    auth_user_id, institution_id, school_id, actor_type, actor_record_id,
    login_identifier, auth_method, status, pin_hash, pin_changed_at, failed_attempts
  ) values (
    p_auth_user_id, p_institution_id, v_effective_school_id, p_actor_type, v_actor_record_id,
    v_login_id, 'pin', 'active', crypt(p_pin, gen_salt('bf')), null, 0
  );

  update public.profiles
  set authority_user_id = p_authority_user_id
  where user_id = p_auth_user_id;
  update public.identity_actors
  set authority_user_id = p_authority_user_id
  where auth_user_id = p_auth_user_id;

  return jsonb_build_object(
    'success', true, 'login_id', v_login_id, 'user_id', p_auth_user_id,
    'profile_id', v_profile_id, 'actor_type', p_actor_type,
    'institution_id', p_institution_id, 'school_id', v_effective_school_id,
    'actor_record_id', v_actor_record_id,
    'full_name', trim(p_full_name),
    'email', nullif(trim(p_email), ''),
    'phone', nullif(trim(p_phone), ''),
    'student_number', v_student_number,
    'pin_requires_change', true
  );
end;
$$;

revoke all on function public.complete_actor_onboarding(uuid,uuid,text,text,uuid,uuid,text,text,text,text,uuid,uuid,uuid[],text,date,text,boolean,uuid,uuid,text,text,text,boolean,integer) from public, anon, authenticated;
grant execute on function public.complete_actor_onboarding(uuid,uuid,text,text,uuid,uuid,text,text,text,text,uuid,uuid,uuid[],text,date,text,boolean,uuid,uuid,text,text,text,boolean,integer) to service_role;

create or replace function public.auth_pin_login(p_identifier text, p_pin text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare v_actor public.identity_actors%rowtype;
begin
  if coalesce(length(p_pin),0) not in (4,6) or nullif(trim(p_identifier),'') is null then
    return jsonb_build_object('success',false,'error','INVALID_CREDENTIALS');
  end if;

  select * into v_actor
  from public.identity_actors
  where upper(login_identifier) = upper(trim(p_identifier))
    and status = 'active'
  limit 1;

  if not found or v_actor.locked_until > now() or v_actor.pin_hash is null
     or crypt(p_pin, v_actor.pin_hash) <> v_actor.pin_hash then
    if found then
      update public.identity_actors
      set failed_attempts = coalesce(failed_attempts,0) + 1,
          locked_until = case when coalesce(failed_attempts,0) + 1 >= 5 then now() + interval '15 minutes' else locked_until end,
          updated_at = now()
      where id = v_actor.id;
    end if;
    return jsonb_build_object('success',false,'error','INVALID_CREDENTIALS');
  end if;

  update public.identity_actors
  set failed_attempts = 0, locked_until = null, last_login_at = now(), updated_at = now()
  where id = v_actor.id;

  return jsonb_build_object(
    'success',true,'user_id',v_actor.auth_user_id,'actor_id',v_actor.id,
    'institution_id',v_actor.institution_id,'school_id',v_actor.school_id,
    'role',v_actor.actor_type,'login_id',v_actor.login_identifier
  );
end;
$$;
revoke all on function public.auth_pin_login(text,text) from public, anon, authenticated;
grant execute on function public.auth_pin_login(text,text) to service_role;

create or replace function public.set_pin(p_new_pin text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $pin$
declare
  v_user_id uuid := auth.uid();
  v_role text;
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;
  select role into v_role from public.profiles where user_id = v_user_id;
  if v_role is null then raise exception 'PROFILE_NOT_FOUND'; end if;
  if length(p_new_pin) not in (4,6) or p_new_pin !~ '^[0-9]{4,6}$'
     or length(p_new_pin) <> case when v_role in ('student','parent') then 4 else 6 end then
    raise exception 'INVALID_PIN_LENGTH';
  end if;
  update public.profiles
  set pin = null, pin_hash = crypt(p_new_pin, gen_salt('bf')),
      pin_changed_at = now(), pin_requires_change = false,
      failed_attempts = 0, locked_until = null
  where user_id = v_user_id;
  update public.identity_actors
  set pin_hash = crypt(p_new_pin, gen_salt('bf')), pin_changed_at = now(),
      failed_attempts = 0, locked_until = null, updated_at = now()
  where auth_user_id = v_user_id;
  return jsonb_build_object('success', true, 'pin_requires_change', false);
end;
$pin$;
revoke all on function public.set_pin(text) from public, anon;
grant execute on function public.set_pin(text) to authenticated;

-- Authenticated users may resolve only their own canonical actor.
alter table public.identity_actors enable row level security;
drop policy if exists identity_actors_select_own on public.identity_actors;
create policy identity_actors_select_own
  on public.identity_actors for select to authenticated
  using (auth_user_id = (select auth.uid()));
revoke all on public.identity_actors from public, anon;
grant select on public.identity_actors to authenticated;

-- Keep profile visibility and mutation scoped to the signed-in account.
drop policy if exists "Users can view their own profile" on public.profiles;
create policy "Users can view their own profile"
  on public.profiles for select to authenticated
  using (user_id = (select auth.uid()));
drop policy if exists "Users can update their own profile" on public.profiles;
create policy "Users can update their own profile"
  on public.profiles for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Domain identity records are visible to their own authenticated identity.
drop policy if exists teachers_select_own on public.teachers;
create policy teachers_select_own on public.teachers for select to authenticated
  using (user_id = (select auth.uid()));
drop policy if exists students_select_own on public.students;
create policy students_select_own on public.students for select to authenticated
  using (user_id = (select auth.uid()));
drop policy if exists lecturers_select_own on public.lecturers;
create policy lecturers_select_own on public.lecturers for select to authenticated
  using (user_id = (select auth.uid()));
drop policy if exists vice_principals_select_own on public.vice_principals;
create policy vice_principals_select_own on public.vice_principals for select to authenticated
  using (exists (
    select 1 from public.profiles p
    where p.id = vice_principals.profile_id and p.user_id = (select auth.uid())
  ));
drop policy if exists bursars_select_own on public.bursars;
create policy bursars_select_own on public.bursars for select to authenticated
  using (exists (
    select 1 from public.profiles p
    where p.id = bursars.profile_id and p.user_id = (select auth.uid())
  ));
drop policy if exists parents_select_own on public.parents;
create policy parents_select_own on public.parents for select to authenticated
  using (exists (
    select 1 from public.profiles p
    where p.id = parents.profile_id and p.user_id = (select auth.uid())
  ));

grant select on public.teachers, public.students, public.lecturers,
  public.vice_principals, public.bursars, public.parents to authenticated;

-- Parent dashboard RPCs must derive the parent from auth.uid(); never trust
-- a caller-supplied parent identifier in SECURITY DEFINER functions.
create or replace function public.get_parent_children(p_parent_id uuid default null)
returns table(
  student_id uuid,
  student_name text,
  class_name text,
  student_number text,
  relationship text,
  is_primary boolean
)
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_profile_id uuid;
  v_parent_id uuid;
begin
  select p.id into v_profile_id
  from public.profiles p
  where p.user_id = auth.uid() and p.role = 'parent';
  if v_profile_id is null then raise exception 'PARENT_AUTH_REQUIRED'; end if;

  select p.id into v_parent_id
  from public.parents p
  where p.profile_id = v_profile_id;
  if v_parent_id is null then raise exception 'PARENT_RECORD_NOT_FOUND'; end if;

  if p_parent_id is not null and p_parent_id not in (v_parent_id, v_profile_id) then
    raise exception 'PARENT_SCOPE_DENIED';
  end if;

  return query
  select s.id, s.first_name || ' ' || s.last_name, c.name,
         s.student_number, spr.relationship_type, spr.is_primary
  from public.student_parent_relationships spr
  join public.students s on s.id = spr.student_id
  join public.classes c on c.id = s.class_id
  where spr.parent_id = v_parent_id
  order by s.first_name;
end;
$;
revoke all on function public.get_parent_children(uuid) from public, anon;
grant execute on function public.get_parent_children(uuid) to authenticated;

create or replace function public.get_parent_dashboard_stats(p_parent_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_profile_id uuid;
  v_parent_id uuid;
  v_parent_name text;
  v_wards jsonb;
begin
  select p.id, p.full_name into v_profile_id, v_parent_name
  from public.profiles p
  where p.user_id = auth.uid() and p.role = 'parent';
  if v_profile_id is null then raise exception 'PARENT_AUTH_REQUIRED'; end if;

  select p.id into v_parent_id
  from public.parents p
  where p.profile_id = v_profile_id;
  if v_parent_id is null then raise exception 'PARENT_RECORD_NOT_FOUND'; end if;

  if p_parent_id is not null and p_parent_id not in (v_parent_id, v_profile_id) then
    raise exception 'PARENT_SCOPE_DENIED';
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'student_id', s.id,
      'student_name', s.first_name || ' ' || s.last_name,
      'student_number', s.student_number,
      'class_name', c.name,
      'class_rank', coalesce((
        select cr.position from public.cbt_results_summary cr
        where cr.student_id = s.id order by cr.created_at desc limit 1
      ), 0),
      'total_students_in_class', (
        select count(*) from public.students classmates where classmates.class_id = s.class_id
      ),
      'attendance_rate', null,
      'term_avg_score', coalesce((
        select avg(cr.percentage) from public.cbt_results_summary cr where cr.student_id = s.id
      ), 0)
    )
  ) into v_wards
  from public.student_parent_relationships spr
  join public.students s on s.id = spr.student_id
  join public.classes c on c.id = s.class_id
  where spr.parent_id = v_parent_id;

  return jsonb_build_object(
    'parent_name', v_parent_name,
    'wards', coalesce(v_wards, '[]'::jsonb),
    'total_wards', coalesce(jsonb_array_length(v_wards), 0)
  );
end;
$;
revoke all on function public.get_parent_dashboard_stats(uuid) from public, anon;
grant execute on function public.get_parent_dashboard_stats(uuid) to authenticated;

-- School-level data RPCs are restricted to the principal for that school or
-- the Dean for the owning institution. They are not public discovery APIs.
create or replace function public.get_school_students(
  p_school_id uuid,
  p_search text default null,
  p_limit integer default 100,
  p_offset integer default 0
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_result jsonb;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.profiles p
    join public.schools s on s.id = p_school_id
    where p.user_id = auth.uid()
      and (
        (p.role = 'principal_admin' and p.school_id = p_school_id)
        or (p.role = 'dean' and p.institution_id = s.institution_id)
      )
  ) then raise exception 'SCHOOL_SCOPE_DENIED'; end if;

  with filtered as (
    select s.id, s.first_name, s.last_name, s.student_number, s.class_id,
           s.gender, s.email, s.phone, s.cgpa, s.enrollment_status, c.name as class_name
    from public.students s
    left join public.classes c on c.id = s.class_id
    where s.school_id = p_school_id
      and (
        p_search is null
        or s.first_name ilike '%' || p_search || '%'
        or s.last_name ilike '%' || p_search || '%'
        or s.student_number ilike '%' || p_search || '%'
      )
  ),
  paged as (
    select * from filtered
    order by last_name, first_name, id
    limit greatest(coalesce(p_limit, 100), 0)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'total', (select count(*) from filtered),
    'students', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id,
        'first_name', first_name,
        'last_name', last_name,
        'student_number', student_number,
        'class_name', class_name,
        'class_id', class_id,
        'gender', gender,
        'email', email,
        'phone', phone,
        'cgpa', cgpa,
        'enrollment_status', enrollment_status
      ) order by last_name, first_name, id)
      from paged
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$;
revoke all on function public.get_school_students(uuid,text,integer,integer) from public, anon;
grant execute on function public.get_school_students(uuid,text,integer,integer) to authenticated;

create or replace function public.get_school_teachers(
  p_school_id uuid,
  p_search text default null,
  p_limit integer default 100,
  p_offset integer default 0
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_result jsonb;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.profiles p
    join public.schools s on s.id = p_school_id
    where p.user_id = auth.uid()
      and (
        (p.role = 'principal_admin' and p.school_id = p_school_id)
        or (p.role = 'dean' and p.institution_id = s.institution_id)
      )
  ) then raise exception 'SCHOOL_SCOPE_DENIED'; end if;

  with filtered as (
    select t.id, t.name, t.email, t.phone
    from public.teachers t
    where t.school_id = p_school_id
      and (
        p_search is null
        or t.name ilike '%' || p_search || '%'
        or t.email ilike '%' || p_search || '%'
      )
  ),
  paged as (
    select * from filtered
    order by name, id
    limit greatest(coalesce(p_limit, 100), 0)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'total', (select count(*) from filtered),
    'teachers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id,
        'name', t.name,
        'email', t.email,
        'phone', t.phone,
        'class_count', (select count(*) from public.teacher_classes tc where tc.teacher_id = t.id),
        'student_count', (
          select count(distinct s.id)
          from public.students s
          join public.teacher_classes tc on tc.class_id = s.class_id
          where tc.teacher_id = t.id
        )
      ) order by t.name, t.id)
      from paged t
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$;
revoke all on function public.get_school_teachers(uuid,text,integer,integer) from public, anon;
grant execute on function public.get_school_teachers(uuid,text,integer,integer) to authenticated;

create or replace function public.get_principal_dashboard_stats(p_school_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_result jsonb;
  v_school_name text;
  v_total_students bigint;
  v_total_teachers bigint;
  v_total_classes bigint;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles p
    where p.user_id = auth.uid()
      and p.role = 'principal_admin'
      and p.school_id = p_school_id
  ) then raise exception 'PRINCIPAL_SCHOOL_SCOPE_DENIED'; end if;

  select school_name into v_school_name from public.schools where id = p_school_id;
  select count(*) into v_total_students from public.students where school_id = p_school_id;
  select count(*) into v_total_teachers from public.teachers where school_id = p_school_id;
  select count(*) into v_total_classes from public.classes where school_id = p_school_id;

  select jsonb_build_object(
    'school_name', v_school_name,
    'total_students', v_total_students,
    'total_teachers', v_total_teachers,
    'total_classes', v_total_classes
  ) into v_result;
  return v_result;
end;
$;
revoke all on function public.get_principal_dashboard_stats(uuid) from public, anon;
grant execute on function public.get_principal_dashboard_stats(uuid) to authenticated;

-- These two legacy dashboard RPCs return hard-coded demonstration content.
-- Keep the functions for reference, but do not serve fabricated records as live data.
revoke all on function public.get_student_dashboard_stats(uuid) from public, anon, authenticated;
revoke all on function public.get_teacher_dashboard_stats(uuid,uuid) from public, anon, authenticated;

-- A profile owner can update presentation fields only. PIN hashes and authority
-- fields are changed through their dedicated trusted functions.
revoke update on table public.profiles from public, anon, authenticated;
grant update(full_name, phone) on table public.profiles to authenticated;

commit;

     or length(p_pin) <> case when p_actor_type in ('student','parent') then 4 else 6 end then
    raise exception 'INVALID_PIN_LENGTH';
  end if;
  if not exists (select 1 from public.institutions i where i.id = p_institution_id) then
    raise exception 'INSTITUTION_NOT_FOUND';
  end if;
  if p_school_id is not null and not exists (
    select 1 from public.schools s where s.id = p_school_id and s.institution_id = p_institution_id
  ) then raise exception 'SCHOOL_INSTITUTION_MISMATCH'; end if;

  if p_actor_type in ('vice_principal','bursar','teacher','student','lecturer') and p_school_id is null then raise exception 'SCHOOL_REQUIRED'; end if;

  v_prefix := case p_actor_type
    when 'vice_principal' then 'VP'
    when 'bursar' then 'BUR'
    when 'teacher' then 'TCH'
    when 'student' then 'STU'
    when 'parent' then 'PAR'
    when 'dean' then 'DEAN'
    when 'hod' then 'HOD'
    when 'adviser' then 'ADV'
    when 'lecturer' then 'LEC'
  end;
  v_login_id := v_prefix || '-' || lpad(nextval('public.actor_login_id_seq')::text, 8, '0');

  if p_actor_type = 'teacher' and coalesce(cardinality(p_class_subject_ids), 0) > 0 then
    if exists (
      select 1
      from unnest(p_class_subject_ids) requested(class_subject_id)
      where not exists (
        select 1 from public.class_subjects cs
        where cs.id = requested.class_subject_id
          and cs.school_id = p_school_id
          and (cs.institution_id is null or cs.institution_id = p_institution_id)
      )
    ) then raise exception 'CLASS_SUBJECT_NOT_IN_SCHOOL'; end if;
  end if;

  if p_actor_type = 'student' then
    if length(trim(p_full_name)) <= length(split_part(trim(p_full_name), ' ', 1)) then raise exception 'STUDENT_LAST_NAME_REQUIRED'; end if;
    if p_class_id is null or not exists (
      select 1 from public.classes c where c.id = p_class_id and c.school_id = p_school_id
    ) then raise exception 'CLASS_NOT_IN_SCHOOL'; end if;
  end if;

  if p_actor_type = 'parent' then
    select s.school_id into v_effective_school_id
    from public.students s
    where s.id = p_student_id
      and s.institution_id = p_institution_id
      and (p_school_id is null or s.school_id = p_school_id);
    if p_student_id is null or not found then raise exception 'LINKED_STUDENT_NOT_FOUND'; end if;
  end if;

  insert into public.profiles (
    user_id, institution_id, school_id, full_name, role, email, phone,
    authentication_method, pin, pin_hash, pin_type, pin_requires_change,
    pin_changed_at, failed_attempts, locked_until
  ) values (
    p_auth_user_id, p_institution_id, v_effective_school_id, trim(p_full_name), p_actor_type,
    nullif(trim(p_email), ''), nullif(trim(p_phone), ''),
    'pin', null, crypt(p_pin, gen_salt('bf')), 
    case when p_actor_type in ('student','parent') then '4-digit' else '6-digit' end,
    true, null, 0, null
  ) returning id into v_profile_id;

  if p_actor_type = 'teacher' then
    insert into public.teachers(user_id, institution_id, school_id, name, email, phone)
    values (p_auth_user_id, p_institution_id, p_school_id, trim(p_full_name),
      nullif(trim(p_email), ''), nullif(trim(p_phone), ''))
    returning id into v_actor_record_id;
    if coalesce(cardinality(p_class_subject_ids), 0) > 0 then
      insert into public.teacher_subject_assignments(school_id, teacher_id, class_subject_id)
      select p_school_id, v_actor_record_id, requested.class_subject_id
      from (
        select distinct unnest(p_class_subject_ids) as class_subject_id
      ) requested;
    end if;
  elsif p_actor_type = 'vice_principal' then
    insert into public.vice_principals(profile_id, school_id, full_name, email, phone)
    values (v_profile_id, p_school_id, trim(p_full_name),
      nullif(trim(p_email), ''), nullif(trim(p_phone), ''))
    returning id into v_actor_record_id;
  elsif p_actor_type = 'bursar' then
    insert into public.bursars(profile_id, school_id, full_name, email, phone)
    values (v_profile_id, p_school_id, trim(p_full_name),
      nullif(trim(p_email), ''), nullif(trim(p_phone), ''))
    returning id into v_actor_record_id;
  elsif p_actor_type = 'student' then
    v_student_number := 'GRD/' || to_char(now(), 'YYYY') || '/' || lpad(nextval('public.student_number_seq')::text, 6, '0');
    insert into public.students(
      user_id, institution_id, school_id, class_id, student_number,
      first_name, last_name, gender, date_of_birth, email, phone
    ) values (
      p_auth_user_id, p_institution_id, p_school_id, p_class_id, v_student_number,
      split_part(trim(p_full_name), ' ', 1),
      nullif(btrim(substr(trim(p_full_name), length(split_part(trim(p_full_name), ' ', 1)) + 2)), ''),
      p_gender, p_date_of_birth, nullif(trim(p_email), ''), nullif(trim(p_phone), '')
    ) returning id into v_actor_record_id;
  elsif p_actor_type in ('dean','hod','adviser') then
    if p_actor_type = 'dean' then
      if p_faculty_id is null or not exists (
        select 1 from public.nuc_faculties nf where nf.id = p_faculty_id and nf.institution_id = p_institution_id
      ) then raise exception 'NUC_FACULTY_NOT_IN_INSTITUTION'; end if;
    elsif p_actor_type = 'hod' then
      if p_department_id is null or not exists (
        select 1 from public.nuc_departments nd where nd.id = p_department_id and nd.institution_id = p_institution_id
      ) then raise exception 'NUC_DEPARTMENT_NOT_IN_INSTITUTION'; end if;
    elsif p_department_id is not null and not exists (
      select 1 from public.departments d where d.id = p_department_id and d.institution_id = p_institution_id
    ) then raise exception 'DEPARTMENT_NOT_IN_INSTITUTION'; end if;

    insert into public.faculty(institution_id, department_id, full_name, email, role)
    values (p_institution_id, case when p_actor_type = 'adviser' then p_department_id else null end,
      trim(p_full_name), coalesce(nullif(trim(p_email), ''), v_login_id || '@accounts.sefaes.invalid'), p_actor_type)
    returning id into v_actor_record_id;

    if p_actor_type = 'dean' then
      update public.nuc_faculties
      set dean_id = v_actor_record_id, dean_name = trim(p_full_name),
          dean_email = nullif(trim(p_email), ''), updated_at = now()
      where id = p_faculty_id and institution_id = p_institution_id;
    elsif p_actor_type = 'hod' then
      update public.nuc_departments
      set hod_id = v_actor_record_id, hod_name = trim(p_full_name),
          hod_email = nullif(trim(p_email), ''), updated_at = now()
      where id = p_department_id and institution_id = p_institution_id;
    end if;
  elsif p_actor_type = 'lecturer' then
    if p_department_id is not null and not exists (
      select 1 from public.nuc_departments d where d.id = p_department_id and d.institution_id = p_institution_id
    ) then raise exception 'NUC_DEPARTMENT_NOT_IN_INSTITUTION'; end if;
    if p_faculty_id is not null and not exists (
      select 1 from public.nuc_faculties f where f.id = p_faculty_id and f.institution_id = p_institution_id
    ) then raise exception 'NUC_FACULTY_NOT_IN_INSTITUTION'; end if;
    if nullif(trim(p_email), '') is null then raise exception 'LECTURER_EMAIL_REQUIRED'; end if;
    insert into public.lecturers(
      school_id, user_id, title, first_name, last_name, email, phone,
      department_id, faculty_id, rank, specialization,
      is_graduate_student_supervisor, max_students
    ) values (
      p_school_id, p_auth_user_id, nullif(trim(p_title), ''),
      split_part(trim(p_full_name), ' ', 1),
      nullif(btrim(substr(trim(p_full_name), length(split_part(trim(p_full_name), ' ', 1)) + 2)), ''),
      trim(p_email), nullif(trim(p_phone), ''), p_department_id, p_faculty_id,
      nullif(trim(p_rank), ''), nullif(trim(p_specialization), ''),
      coalesce(p_is_graduate_student_supervisor, false), p_max_students
    ) returning id into v_actor_record_id;
  elsif p_actor_type = 'parent' then
    insert into public.parents(institution_id, profile_id, child_student_id)
    values (p_institution_id, v_profile_id, p_student_id)
    returning id into v_actor_record_id;
    insert into public.student_parents(student_id, parent_id, relationship, is_primary)
    values (p_student_id, v_actor_record_id, coalesce(nullif(trim(p_relationship), ''), 'Parent'), coalesce(p_is_primary, true));
    insert into public.student_parent_relationships(
      institution_id, school_id, student_id, parent_id, relationship_type, is_primary
    ) values (
      p_institution_id, v_effective_school_id, p_student_id, v_actor_record_id,
      case lower(coalesce(nullif(trim(p_relationship), ''), 'other'))
        when 'father' then 'father'
        when 'mother' then 'mother'
        when 'guardian' then 'guardian'
        else 'other'
      end,
      coalesce(p_is_primary, true)
    );
  end if;

  insert into public.identity_actors(
    auth_user_id, institution_id, school_id, actor_type, actor_record_id,
    login_identifier, auth_method, status, pin_hash, pin_changed_at, failed_attempts
  ) values (
    p_auth_user_id, p_institution_id, v_effective_school_id, p_actor_type, v_actor_record_id,
    v_login_id, 'pin', 'active', crypt(p_pin, gen_salt('bf')), null, 0
  );

  update public.profiles
  set authority_user_id = p_authority_user_id
  where user_id = p_auth_user_id;
  update public.identity_actors
  set authority_user_id = p_authority_user_id
  where auth_user_id = p_auth_user_id;

  return jsonb_build_object(
    'success', true, 'login_id', v_login_id, 'user_id', p_auth_user_id,
    'profile_id', v_profile_id, 'actor_type', p_actor_type,
    'institution_id', p_institution_id, 'school_id', v_effective_school_id,
    'actor_record_id', v_actor_record_id,
    'full_name', trim(p_full_name),
    'email', nullif(trim(p_email), ''),
    'phone', nullif(trim(p_phone), ''),
    'student_number', v_student_number,
    'pin_requires_change', true
  );
end;
$$;

revoke all on function public.complete_actor_onboarding(uuid,uuid,text,text,uuid,uuid,text,text,text,text,uuid,uuid,uuid[],text,date,text,boolean,uuid,uuid,text,text,text,boolean,integer) from public, anon, authenticated;
grant execute on function public.complete_actor_onboarding(uuid,uuid,text,text,uuid,uuid,text,text,text,text,uuid,uuid,uuid[],text,date,text,boolean,uuid,uuid,text,text,text,boolean,integer) to service_role;

create or replace function public.auth_pin_login(p_identifier text, p_pin text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare v_actor public.identity_actors%rowtype;
begin
  if coalesce(length(p_pin),0) not in (4,6) or nullif(trim(p_identifier),'') is null then
    return jsonb_build_object('success',false,'error','INVALID_CREDENTIALS');
  end if;

  select * into v_actor
  from public.identity_actors
  where upper(login_identifier) = upper(trim(p_identifier))
    and status = 'active'
  limit 1;

  if not found or v_actor.locked_until > now() or v_actor.pin_hash is null
     or crypt(p_pin, v_actor.pin_hash) <> v_actor.pin_hash then
    if found then
      update public.identity_actors
      set failed_attempts = coalesce(failed_attempts,0) + 1,
          locked_until = case when coalesce(failed_attempts,0) + 1 >= 5 then now() + interval '15 minutes' else locked_until end,
          updated_at = now()
      where id = v_actor.id;
    end if;
    return jsonb_build_object('success',false,'error','INVALID_CREDENTIALS');
  end if;

  update public.identity_actors
  set failed_attempts = 0, locked_until = null, last_login_at = now(), updated_at = now()
  where id = v_actor.id;

  return jsonb_build_object(
    'success',true,'user_id',v_actor.auth_user_id,'actor_id',v_actor.id,
    'institution_id',v_actor.institution_id,'school_id',v_actor.school_id,
    'role',v_actor.actor_type,'login_id',v_actor.login_identifier
  );
end;
$$;
revoke all on function public.auth_pin_login(text,text) from public, anon, authenticated;
grant execute on function public.auth_pin_login(text,text) to service_role;

create or replace function public.set_pin(p_new_pin text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $pin$
declare
  v_user_id uuid := auth.uid();
  v_role text;
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;
  select role into v_role from public.profiles where user_id = v_user_id;
  if v_role is null then raise exception 'PROFILE_NOT_FOUND'; end if;
  if length(p_new_pin) not in (4,6) or p_new_pin !~ '^[0-9]{4,6}$'
     or length(p_new_pin) <> case when v_role in ('student','parent') then 4 else 6 end then
    raise exception 'INVALID_PIN_LENGTH';
  end if;
  update public.profiles
  set pin = null, pin_hash = crypt(p_new_pin, gen_salt('bf')),
      pin_changed_at = now(), pin_requires_change = false,
      failed_attempts = 0, locked_until = null
  where user_id = v_user_id;
  update public.identity_actors
  set pin_hash = crypt(p_new_pin, gen_salt('bf')), pin_changed_at = now(),
      failed_attempts = 0, locked_until = null, updated_at = now()
  where auth_user_id = v_user_id;
  return jsonb_build_object('success', true, 'pin_requires_change', false);
end;
$pin$;
revoke all on function public.set_pin(text) from public, anon;
grant execute on function public.set_pin(text) to authenticated;

-- Authenticated users may resolve only their own canonical actor.
alter table public.identity_actors enable row level security;
drop policy if exists identity_actors_select_own on public.identity_actors;
create policy identity_actors_select_own
  on public.identity_actors for select to authenticated
  using (auth_user_id = (select auth.uid()));
revoke all on public.identity_actors from public, anon;
grant select on public.identity_actors to authenticated;

-- Keep profile visibility and mutation scoped to the signed-in account.
drop policy if exists "Users can view their own profile" on public.profiles;
create policy "Users can view their own profile"
  on public.profiles for select to authenticated
  using (user_id = (select auth.uid()));
drop policy if exists "Users can update their own profile" on public.profiles;
create policy "Users can update their own profile"
  on public.profiles for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Domain identity records are visible to their own authenticated identity.
drop policy if exists teachers_select_own on public.teachers;
create policy teachers_select_own on public.teachers for select to authenticated
  using (user_id = (select auth.uid()));
drop policy if exists students_select_own on public.students;
create policy students_select_own on public.students for select to authenticated
  using (user_id = (select auth.uid()));
drop policy if exists lecturers_select_own on public.lecturers;
create policy lecturers_select_own on public.lecturers for select to authenticated
  using (user_id = (select auth.uid()));
drop policy if exists vice_principals_select_own on public.vice_principals;
create policy vice_principals_select_own on public.vice_principals for select to authenticated
  using (exists (
    select 1 from public.profiles p
    where p.id = vice_principals.profile_id and p.user_id = (select auth.uid())
  ));
drop policy if exists bursars_select_own on public.bursars;
create policy bursars_select_own on public.bursars for select to authenticated
  using (exists (
    select 1 from public.profiles p
    where p.id = bursars.profile_id and p.user_id = (select auth.uid())
  ));
drop policy if exists parents_select_own on public.parents;
create policy parents_select_own on public.parents for select to authenticated
  using (exists (
    select 1 from public.profiles p
    where p.id = parents.profile_id and p.user_id = (select auth.uid())
  ));

grant select on public.teachers, public.students, public.lecturers,
  public.vice_principals, public.bursars, public.parents to authenticated;

-- Parent dashboard RPCs must derive the parent from auth.uid(); never trust
-- a caller-supplied parent identifier in SECURITY DEFINER functions.
create or replace function public.get_parent_children(p_parent_id uuid default null)
returns table(
  student_id uuid,
  student_name text,
  class_name text,
  student_number text,
  relationship text,
  is_primary boolean
)
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_profile_id uuid;
  v_parent_id uuid;
begin
  select p.id into v_profile_id
  from public.profiles p
  where p.user_id = auth.uid() and p.role = 'parent';
  if v_profile_id is null then raise exception 'PARENT_AUTH_REQUIRED'; end if;

  select p.id into v_parent_id
  from public.parents p
  where p.profile_id = v_profile_id;
  if v_parent_id is null then raise exception 'PARENT_RECORD_NOT_FOUND'; end if;

  if p_parent_id is not null and p_parent_id not in (v_parent_id, v_profile_id) then
    raise exception 'PARENT_SCOPE_DENIED';
  end if;

  return query
  select s.id, s.first_name || ' ' || s.last_name, c.name,
         s.student_number, spr.relationship_type, spr.is_primary
  from public.student_parent_relationships spr
  join public.students s on s.id = spr.student_id
  join public.classes c on c.id = s.class_id
  where spr.parent_id = v_parent_id
  order by s.first_name;
end;
$;
revoke all on function public.get_parent_children(uuid) from public, anon;
grant execute on function public.get_parent_children(uuid) to authenticated;

create or replace function public.get_parent_dashboard_stats(p_parent_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_profile_id uuid;
  v_parent_id uuid;
  v_parent_name text;
  v_wards jsonb;
begin
  select p.id, p.full_name into v_profile_id, v_parent_name
  from public.profiles p
  where p.user_id = auth.uid() and p.role = 'parent';
  if v_profile_id is null then raise exception 'PARENT_AUTH_REQUIRED'; end if;

  select p.id into v_parent_id
  from public.parents p
  where p.profile_id = v_profile_id;
  if v_parent_id is null then raise exception 'PARENT_RECORD_NOT_FOUND'; end if;

  if p_parent_id is not null and p_parent_id not in (v_parent_id, v_profile_id) then
    raise exception 'PARENT_SCOPE_DENIED';
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'student_id', s.id,
      'student_name', s.first_name || ' ' || s.last_name,
      'student_number', s.student_number,
      'class_name', c.name,
      'class_rank', coalesce((
        select cr.position from public.cbt_results_summary cr
        where cr.student_id = s.id order by cr.created_at desc limit 1
      ), 0),
      'total_students_in_class', (
        select count(*) from public.students classmates where classmates.class_id = s.class_id
      ),
      'attendance_rate', null,
      'term_avg_score', coalesce((
        select avg(cr.percentage) from public.cbt_results_summary cr where cr.student_id = s.id
      ), 0)
    )
  ) into v_wards
  from public.student_parent_relationships spr
  join public.students s on s.id = spr.student_id
  join public.classes c on c.id = s.class_id
  where spr.parent_id = v_parent_id;

  return jsonb_build_object(
    'parent_name', v_parent_name,
    'wards', coalesce(v_wards, '[]'::jsonb),
    'total_wards', coalesce(jsonb_array_length(v_wards), 0)
  );
end;
$;
revoke all on function public.get_parent_dashboard_stats(uuid) from public, anon;
grant execute on function public.get_parent_dashboard_stats(uuid) to authenticated;

-- School-level data RPCs are restricted to the principal for that school or
-- the Dean for the owning institution. They are not public discovery APIs.
create or replace function public.get_school_students(
  p_school_id uuid,
  p_search text default null,
  p_limit integer default 100,
  p_offset integer default 0
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_result jsonb;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.profiles p
    join public.schools s on s.id = p_school_id
    where p.user_id = auth.uid()
      and (
        (p.role = 'principal_admin' and p.school_id = p_school_id)
        or (p.role = 'dean' and p.institution_id = s.institution_id)
      )
  ) then raise exception 'SCHOOL_SCOPE_DENIED'; end if;

  with filtered as (
    select s.id, s.first_name, s.last_name, s.student_number, s.class_id,
           s.gender, s.email, s.phone, s.cgpa, s.enrollment_status, c.name as class_name
    from public.students s
    left join public.classes c on c.id = s.class_id
    where s.school_id = p_school_id
      and (
        p_search is null
        or s.first_name ilike '%' || p_search || '%'
        or s.last_name ilike '%' || p_search || '%'
        or s.student_number ilike '%' || p_search || '%'
      )
  ),
  paged as (
    select * from filtered
    order by last_name, first_name, id
    limit greatest(coalesce(p_limit, 100), 0)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'total', (select count(*) from filtered),
    'students', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id,
        'first_name', first_name,
        'last_name', last_name,
        'student_number', student_number,
        'class_name', class_name,
        'class_id', class_id,
        'gender', gender,
        'email', email,
        'phone', phone,
        'cgpa', cgpa,
        'enrollment_status', enrollment_status
      ) order by last_name, first_name, id)
      from paged
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$;
revoke all on function public.get_school_students(uuid,text,integer,integer) from public, anon;
grant execute on function public.get_school_students(uuid,text,integer,integer) to authenticated;

create or replace function public.get_school_teachers(
  p_school_id uuid,
  p_search text default null,
  p_limit integer default 100,
  p_offset integer default 0
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_result jsonb;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.profiles p
    join public.schools s on s.id = p_school_id
    where p.user_id = auth.uid()
      and (
        (p.role = 'principal_admin' and p.school_id = p_school_id)
        or (p.role = 'dean' and p.institution_id = s.institution_id)
      )
  ) then raise exception 'SCHOOL_SCOPE_DENIED'; end if;

  with filtered as (
    select t.id, t.name, t.email, t.phone
    from public.teachers t
    where t.school_id = p_school_id
      and (
        p_search is null
        or t.name ilike '%' || p_search || '%'
        or t.email ilike '%' || p_search || '%'
      )
  ),
  paged as (
    select * from filtered
    order by name, id
    limit greatest(coalesce(p_limit, 100), 0)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'total', (select count(*) from filtered),
    'teachers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id,
        'name', t.name,
        'email', t.email,
        'phone', t.phone,
        'class_count', (select count(*) from public.teacher_classes tc where tc.teacher_id = t.id),
        'student_count', (
          select count(distinct s.id)
          from public.students s
          join public.teacher_classes tc on tc.class_id = s.class_id
          where tc.teacher_id = t.id
        )
      ) order by t.name, t.id)
      from paged t
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$;
revoke all on function public.get_school_teachers(uuid,text,integer,integer) from public, anon;
grant execute on function public.get_school_teachers(uuid,text,integer,integer) to authenticated;

create or replace function public.get_principal_dashboard_stats(p_school_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $
declare
  v_result jsonb;
  v_school_name text;
  v_total_students bigint;
  v_total_teachers bigint;
  v_total_classes bigint;
begin
  if auth.uid() is null or not exists (
    select 1 from public.profiles p
    where p.user_id = auth.uid()
      and p.role = 'principal_admin'
      and p.school_id = p_school_id
  ) then raise exception 'PRINCIPAL_SCHOOL_SCOPE_DENIED'; end if;

  select school_name into v_school_name from public.schools where id = p_school_id;
  select count(*) into v_total_students from public.students where school_id = p_school_id;
  select count(*) into v_total_teachers from public.teachers where school_id = p_school_id;
  select count(*) into v_total_classes from public.classes where school_id = p_school_id;

  select jsonb_build_object(
    'school_name', v_school_name,
    'total_students', v_total_students,
    'total_teachers', v_total_teachers,
    'total_classes', v_total_classes
  ) into v_result;
  return v_result;
end;
$;
revoke all on function public.get_principal_dashboard_stats(uuid) from public, anon;
grant execute on function public.get_principal_dashboard_stats(uuid) to authenticated;

-- These two legacy dashboard RPCs return hard-coded demonstration content.
-- Keep the functions for reference, but do not serve fabricated records as live data.
revoke all on function public.get_student_dashboard_stats(uuid) from public, anon, authenticated;
revoke all on function public.get_teacher_dashboard_stats(uuid,uuid) from public, anon, authenticated;

-- A profile owner can update presentation fields only. PIN hashes and authority
-- fields are changed through their dedicated trusted functions.
revoke update on table public.profiles from public, anon, authenticated;
grant update(full_name, phone) on table public.profiles to authenticated;

commit;
